/* C&D V53: fuente completa del Worker y sus recursos, comprimida sin dependencias. */
const source=require('node:zlib').gunzipSync(Buffer.from("",'base64')).toString('utf8');
let depth=0,quoted=false,escape=false,end=0;const start=source.indexOf('{');for(let i=start;i<source.length;i++){const c=source[i];if(quoted){if(escape)escape=false;else if(c==='\\')escape=true;else if(c==='"')quoted=false;}else if(c==='"')quoted=true;else if(c==='{')depth++;else if(c==='}'&&--depth===0){end=i+1;break;}}
module.exports={workerSource:source,assets:JSON.parse(source.slice(start,end))};
